('admin', 'info@wetruenorthgroup.com', '$2y$10$QkC.S3.Z4Z/6gq9gA1H5/e/dO8h5rJk3Ff0R.x.X.Y.X.Y.X.Y.X', 'Super Admin', 'active')
INSERT INTO `categories` (`name`, `slug`, `image`, `cover_image`, `description`, `sort_order`, `status`) VALUES
('PET bottles', 'pet-bottles', '/vikaas_inputs/thumbnails/thumbnail_pet_bottles.png', '/vikaas_inputs/pharma_bottles.png', 'Precision injection blow-moulded PET bottles from 10ml to 1,000ml in cylindrical, Boston, dome, oval, and custom configurations.', 1, 'published'),
('HDPE bottles', 'hdpe-bottles', '/brand_assets/pet_bottles/100ml_boston_white.jpeg', '/vikaas_inputs/pharma_bottles.png', 'Chemical-resistant HDPE containers engineered for pharmaceutical syrups, laboratory reagents, and industrial applications.', 2, 'published'),
('Caps', 'caps', '/brand_assets/caps/nb108-i.png', '/vikaas_inputs/cosmetics.png', 'Engineered screw closures, flip top caps, disc top caps, child-resistant caps (CRC), and tamper-evident ROPP finishes.', 3, 'published'),
('Pumps', 'pumps', '/brand_assets/pumps/nb101-a.png', '/vikaas_inputs/cosmetics.png', 'Cosmetic lotion pumps, treatment dispensers, and saddle pumps with precision 1.2cc to 4.0cc dosage outputs.', 4, 'published'),
('Finger sprayer', 'finger-sprayers', '/brand_assets/sprays/nb304-a.png', '/vikaas_inputs/cosmetics.png', 'Ultra-fine atomization mist sprayers with protective clear overcaps for toners, fragrances, and antiseptic formulations.', 5, 'published'),
('Trigger sprayer', 'trigger-sprayers', '/brand_assets/sprays/nb201-a.png', '/vikaas_inputs/agro_pesticides.jpg', 'Heavy-duty ergonomic trigger sprayers and chemical-resistant industrial spray heads with stream and mist options.', 6, 'published'),
('PET jars', 'pet-jars', '/vikaas_inputs/thumbnails/thumbnail_nutraceuticle_jars.jpg', '/vikaas_inputs/pet_nutraceuticle_jars.png', 'Nutraceutical tablet jars, wide-mouth capsule containers, and cosmetic cream jars from 75cc to 500cc.', 7, 'published'),
('Lids', 'lids', '/brand_assets/glass_bottles/metal_unishell_cap_.jpg', '/vikaas_inputs/cosmetics.png', 'Aluminum metal unishell lids, smooth ribbed screw caps, and induction heat-seal closures.', 8, 'published'),
('PP jars', 'pp-jars', '/brand_assets/pet_bottles/75cc_blue_jar.jpeg', '/vikaas_inputs/pet_nutraceuticle_jars.png', 'Double-wall luxury cosmetic jars and single-wall polypropylene jars with airtight interior shives.', 9, 'published'),
('Mono material jar', 'mono-material-jars', '/vikaas_inputs/pet_nutraceuticle_jars.png', '/vikaas_inputs/cosmetics.png', '100% single-polymer recyclable PP jars aligned with circular packaging and ESG standards.', 10, 'published'),
('Foamer pumps', 'foamer-pumps', '/brand_assets/pet_bottles/veola_50ml.jpg', '/vikaas_inputs/cosmetics.png', 'Propellant-free foaming dispenser bottles creating rich micro-foam for face washes and dermatological scrubs.', 11, 'published'),
('Airless', 'airless', '/brand_assets/pet_bottles/100ml_bulb_bottle.jpg', '/vikaas_inputs/cosmetics.png', 'Piston-driven vacuum airless bottles and bulb active dispensers protecting sensitive cosmetics from oxidation.', 12, 'published');
